-- Courses
INSERT INTO courses (slug, title, subtitle, category, level, language, description, what_you_learn, duration_minutes, price_usd, rating, rating_count, instructor_name, instructor_bio, cover_gradient, is_featured, created_at)
VALUES ('ai-basics-for-everyone', 'AI Basics for Everyone', 'Understand AI and use it confidently in daily life', 'AI Basics', 'Beginner', 'English', 'A warm, jargon-free introduction to artificial intelligence. You will learn what AI really is, try your first conversations with an AI assistant, learn to check its answers and use it safely for everyday tasks at home and at work.', '["Explain what AI and large language models are in plain words","Hold useful conversations with tools like ChatGPT, Gemini and Claude","Fact-check AI answers and spot common mistakes","Protect your private data when using AI","Save time on everyday tasks with simple prompts"]'::jsonb, 47, 0, 4.8, 20311, 'Lucas Martin', 'Lucas has taught digital skills to 90,000 adults across France and West Africa and believes AI should feel friendly, not frightening.', '["#4f46e5","#2563eb"]'::jsonb, TRUE, now() - interval '206 days 0 hours')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, subtitle, category, level, language, description, what_you_learn, duration_minutes, price_usd, rating, rating_count, instructor_name, instructor_bio, cover_gradient, is_featured, created_at)
VALUES ('how-machine-learning-really-works', 'How Machine Learning Really Works', 'From data to predictions — no maths degree needed', 'AI Basics', 'Intermediate', 'English', 'Look under the hood of machine learning. Using clear visuals and real examples, you will understand training data, models, evaluation and the limits of AI — so you can make smarter decisions about where to use it.', '["Describe how models learn from training data","Tell the difference between supervised, unsupervised and generative AI","Read accuracy, precision and recall without fear","Recognise bias and data quality problems","Ask the right questions before trusting an AI system"]'::jsonb, 55, 35, 4.7, 2870, 'Yuki Tanaka', 'Yuki is a data scientist in Tokyo who builds recommendation systems and loves explaining complex ideas with everyday examples.', '["#0ea5e9","#4f46e5"]'::jsonb, FALSE, now() - interval '192 days 0 hours')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, subtitle, category, level, language, description, what_you_learn, duration_minutes, price_usd, rating, rating_count, instructor_name, instructor_bio, cover_gradient, is_featured, created_at)
VALUES ('responsible-ai-in-practice', 'Responsible AI in Practice', 'Fair, safe and trustworthy AI for real organisations', 'AI Basics', 'Advanced', 'English', 'Move from principles to practice. Learn how to assess AI risks, design human oversight, document systems and respond when things go wrong — with templates you can use in any organisation.', '["Run a practical AI risk assessment","Design meaningful human oversight","Write clear AI use policies","Document systems for audits and regulators","Plan incident response for AI failures"]'::jsonb, 46, 59, 4.8, 1420, 'Hannah Becker', 'Hannah advises European public bodies and NGOs on AI governance, risk and ethics.', '["#7c3aed","#10b981"]'::jsonb, FALSE, now() - interval '317 days 0 hours')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, subtitle, category, level, language, description, what_you_learn, duration_minutes, price_usd, rating, rating_count, instructor_name, instructor_bio, cover_gradient, is_featured, created_at)
VALUES ('prompt-engineering-foundations', 'Prompt Engineering Foundations', 'Write prompts that get great answers the first time', 'Prompt Engineering', 'Beginner', 'English', 'The essential prompting course. Learn the role–task–context–format formula, give examples, break big jobs into steps and build a reusable prompt library you will use every day.', '["Use the role · task · context · format formula","Improve answers with examples (few-shot prompting)","Break complex work into prompt chains","Fix vague or wrong answers quickly","Build your own reusable prompt library"]'::jsonb, 47, 0, 4.9, 12840, 'Amara Okafor', 'Amara leads AI enablement for a Lagos fintech and has trained thousands of professionals to write better prompts.', '["#7c3aed","#db2777"]'::jsonb, TRUE, now() - interval '138 days 0 hours')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, subtitle, category, level, language, description, what_you_learn, duration_minutes, price_usd, rating, rating_count, instructor_name, instructor_bio, cover_gradient, is_featured, created_at)
VALUES ('prompt-engineering-for-professionals-arabic', 'هندسة الأوامر للمحترفين', 'Prompt Engineering for Professionals (taught in Arabic)', 'Prompt Engineering', 'Intermediate', 'Arabic', 'A practical prompting course taught in Arabic for professionals across the Middle East and North Africa: writing, analysis, research and bilingual work with AI.', '["Write precise prompts for professional tasks","Work bilingually in Arabic and English with AI","Use AI for research and analysis","Create reusable templates for your team"]'::jsonb, 44, 39, 4.8, 2980, 'Omar Haddad', 'Omar is a Jordanian product manager who teaches Arabic-speaking teams to use AI for writing, research and analysis.', '["#be185d","#7c3aed"]'::jsonb, FALSE, now() - interval '158 days 0 hours')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, subtitle, category, level, language, description, what_you_learn, duration_minutes, price_usd, rating, rating_count, instructor_name, instructor_bio, cover_gradient, is_featured, created_at)
VALUES ('advanced-prompt-patterns', 'Advanced Prompt Patterns', 'Structured output, self-critique and prompt chains', 'Prompt Engineering', 'Advanced', 'English', 'Go beyond chat. Learn the patterns AI engineers use to get reliable, structured, testable results: JSON output, self-critique loops, prompt chains, evaluation sets and guardrails.', '["Get reliable structured output such as JSON","Use self-critique and reflection loops","Design multi-step prompt chains","Build evaluation sets to test prompts","Add guardrails against misuse"]'::jsonb, 56, 69, 4.9, 1610, 'Mei Lin', 'Mei is an AI engineer in Singapore who designs prompt pipelines for customer support and analytics products.', '["#2563eb","#c026d3"]'::jsonb, FALSE, now() - interval '61 days 0 hours')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, subtitle, category, level, language, description, what_you_learn, duration_minutes, price_usd, rating, rating_count, instructor_name, instructor_bio, cover_gradient, is_featured, created_at)
VALUES ('ai-strategy-for-small-businesses', 'AI Strategy for Small Businesses', 'Find, test and scale the AI wins that matter', 'AI for Business', 'Intermediate', 'English', 'A step-by-step playbook for owners and managers: identify high-value use cases, run a low-risk pilot, measure return on investment and roll AI out to your team with confidence.', '["Spot high-value, low-risk AI use cases","Run a two-week pilot with clear metrics","Calculate the ROI of an AI tool","Write a one-page AI policy","Train and motivate your team"]'::jsonb, 54, 49, 4.7, 3120, 'Priya Raman', 'Priya has helped 200+ small businesses in India and the Gulf adopt AI, from bakeries to logistics firms.', '["#0891b2","#4f46e5"]'::jsonb, TRUE, now() - interval '89 days 0 hours')
ON CONFLICT (slug) DO NOTHING;
