VALUES ('ai-powered-marketing', 'AI-Powered Marketing', 'Campaigns, content and insights with AI', 'AI for Business', 'Intermediate', 'English', 'Plan campaigns, create on-brand content, personalise messages and analyse results with AI — without losing the human creativity that makes marketing work.', '["Define and apply a brand voice with AI","Plan multi-channel campaigns quickly","Create and test ad variations","Analyse campaign results with AI"]'::jsonb, 43, 45, 4.8, 2240, 'Carlos Mendes', 'Carlos ran growth marketing for startups in São Paulo and Lisbon and now teaches AI-first marketing.', '["#db2777","#f59e0b"]'::jsonb, FALSE, now() - interval '370 days 0 hours')
