VALUES ('building-ai-agents-with-claude', 'Building AI Agents with Claude', 'Design, build and safely ship tool-using agents', 'AI Agents', 'Advanced', 'English', 'Learn to design agents that plan, use tools and know when to stop. You will define tools, manage memory and context, add human approval and evaluate your agent before shipping.', '["Explain the agent loop: think, act, observe","Design clear, well-described tools","Manage memory and context windows","Add human approval for risky actions","Evaluate and monitor agents in production"]'::jsonb, 68, 89, 4.9, 2210, 'Daniel Kim', 'Daniel builds production AI agents in Seoul and has shipped assistants used by millions of customers.', '["#9333ea","#2563eb"]'::jsonb, TRUE, now() - interval '187 days 0 hours')
