VALUES ('agentes-de-ia-sin-codigo', 'Agentes de IA sin código', 'No-code AI Agents (taught in Spanish)', 'AI Agents', 'Intermediate', 'Spanish', 'Build useful AI agents with no-code tools, taught in Spanish: automate email triage, lead follow-up and reporting, with safety checks built in.', '["Plan an agent with a one-sentence job description","Connect no-code tools and triggers","Add approval steps for risky actions","Test and improve your agent"]'::jsonb, 40, 45, 4.8, 2430, 'Sofía Ramírez', 'Sofía is an automation specialist in Mexico City who helps teams build agents without writing code.', '["#db2777","#9333ea"]'::jsonb, FALSE, now() - interval '80 days 0 hours')
