-- Lessons (first lesson of each course is a free preview)
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'What AI is (and is not)', 1, 9, 'https://videos.novaris.example/ai-basics-for-everyone/lesson-1.mp4', 'Modern AI learns patterns from huge amounts of data instead of following hand-written rules.
Language models predict likely text, which is why they can sound confident and still be wrong.
Think of AI as a capable assistant that amplifies your judgment — not a replacement for it.', TRUE FROM courses WHERE slug = 'ai-basics-for-everyone'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Your first conversations', 2, 11, 'https://videos.novaris.example/ai-basics-for-everyone/lesson-2.mp4', 'Start with context: who you are, what you need and who the result is for.
Follow up. The second and third replies are often far better than the first.
Ask for formats you can use straight away — tables, checklists, emails or step-by-step plans.', FALSE FROM courses WHERE slug = 'ai-basics-for-everyone'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Checking facts and spotting mistakes', 3, 10, 'https://videos.novaris.example/ai-basics-for-everyone/lesson-3.mp4', 'Always verify names, numbers, dates, prices and quotes against a second source.
Ask the AI which parts of its answer it is least sure about — it will often tell you.
Be extra careful with health, legal and financial topics, where mistakes are costly.', FALSE FROM courses WHERE slug = 'ai-basics-for-everyone'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Staying safe and private', 4, 8, 'https://videos.novaris.example/ai-basics-for-everyone/lesson-4.mp4', 'Never paste passwords, ID numbers, bank details or private client data into public AI tools.
Check your organisation’s AI policy before using work documents.
Use approved business versions of AI tools when you work with sensitive information.', FALSE FROM courses WHERE slug = 'ai-basics-for-everyone'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'AI in everyday life', 5, 9, 'https://videos.novaris.example/ai-basics-for-everyone/lesson-5.mp4', 'Use AI to translate, summarise, plan, brainstorm and learn faster.
Small daily wins add up: 15 minutes saved a day is more than 50 hours a year.
Pick one routine task this week and try doing it with AI.', FALSE FROM courses WHERE slug = 'ai-basics-for-everyone'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Data is the new teacher', 1, 10, 'https://videos.novaris.example/how-machine-learning-really-works/lesson-1.mp4', 'A model learns by finding patterns in examples, called training data.
More data helps, but better data helps more: clean, relevant and representative.
If the data is biased or out of date, the model will be too.', TRUE FROM courses WHERE slug = 'how-machine-learning-really-works'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Supervised, unsupervised and generative', 2, 12, 'https://videos.novaris.example/how-machine-learning-really-works/lesson-2.mp4', 'Supervised learning uses labelled examples, such as emails marked “spam” or “not spam”.
Unsupervised learning finds groups in unlabelled data, such as customer segments.
Generative models create new content — text, images or code — based on what they learned.', FALSE FROM courses WHERE slug = 'how-machine-learning-really-works'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Training, testing and overfitting', 3, 11, 'https://videos.novaris.example/how-machine-learning-really-works/lesson-3.mp4', 'We train on one part of the data and test on another part the model has never seen.
Overfitting means the model memorised the training data but fails on new examples.
A good model performs well on fresh data, not just familiar data.', FALSE FROM courses WHERE slug = 'how-machine-learning-really-works'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Measuring how good a model is', 4, 12, 'https://videos.novaris.example/how-machine-learning-really-works/lesson-4.mp4', 'Accuracy is the share of correct predictions, but it can mislead when one outcome is rare.
Precision asks: when the model says yes, how often is it right? Recall asks: how many real yeses did it find?
Choose the measure that matches the cost of mistakes in your situation.', FALSE FROM courses WHERE slug = 'how-machine-learning-really-works'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Bias, limits and asking good questions', 5, 10, 'https://videos.novaris.example/how-machine-learning-really-works/lesson-5.mp4', 'Bias enters through data, labels and how a system is used.
Ask: who is missing from the data? Who could be harmed by a mistake? Who checks the results?
Trust AI systems that are tested, monitored and explained — not just impressive in demos.', FALSE FROM courses WHERE slug = 'how-machine-learning-really-works'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'From principles to practice', 1, 12, 'https://videos.novaris.example/responsible-ai-in-practice/lesson-1.mp4', 'Fairness, transparency, privacy, safety and accountability are the core principles.
Principles only matter when they become checklists, roles and decisions.
Start small: one register of every AI system your organisation uses.', TRUE FROM courses WHERE slug = 'responsible-ai-in-practice'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Assessing AI risk', 2, 13, 'https://videos.novaris.example/responsible-ai-in-practice/lesson-2.mp4', 'Rate each use case by impact on people and likelihood of harm.
High-impact uses — hiring, lending, health, education decisions — need the strongest controls.
Record the risks, the controls and who signs off.', FALSE FROM courses WHERE slug = 'responsible-ai-in-practice'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Human oversight that works', 3, 11, 'https://videos.novaris.example/responsible-ai-in-practice/lesson-3.mp4', 'Oversight fails when people rubber-stamp AI output without time or authority to challenge it.
Give reviewers clear criteria, enough time and the power to override.
Measure how often humans disagree with the AI — zero disagreement is a warning sign.', FALSE FROM courses WHERE slug = 'responsible-ai-in-practice'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'When things go wrong', 4, 10, 'https://videos.novaris.example/responsible-ai-in-practice/lesson-4.mp4', 'Plan incident response before launch: how to detect, pause, investigate and communicate.
Keep logs so you can reconstruct what the system did and why.
Share lessons learned so the same failure does not happen twice.', FALSE FROM courses WHERE slug = 'responsible-ai-in-practice'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'What makes a great prompt', 1, 9, 'https://videos.novaris.example/prompt-engineering-foundations/lesson-1.mp4', 'A prompt is a brief: give the model a role, a task, context and the format you want back.
Specific beats clever. “Summarise this for a busy CFO in 5 bullets” beats “summarise this”.
Always say what good looks like — length, tone and audience.', TRUE FROM courses WHERE slug = 'prompt-engineering-foundations'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Giving examples (few-shot prompting)', 2, 11, 'https://videos.novaris.example/prompt-engineering-foundations/lesson-2.mp4', 'Showing 2–3 examples of input → output teaches the model your pattern.
Keep examples consistent in format, or the model will mix styles.
Examples are the fastest fix when the tone is “almost right”.', FALSE FROM courses WHERE slug = 'prompt-engineering-foundations'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Step-by-step reasoning', 3, 10, 'https://videos.novaris.example/prompt-engineering-foundations/lesson-3.mp4', 'For tricky tasks, ask the model to plan first, then answer.
Break big jobs into a chain of smaller prompts you can check one by one.
Ask the model to check its own answer against your criteria.', FALSE FROM courses WHERE slug = 'prompt-engineering-foundations'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Fixing weak answers', 4, 9, 'https://videos.novaris.example/prompt-engineering-foundations/lesson-4.mp4', 'Too vague? Add audience, goal and format. Too long? Reply “half the length, same meaning”.
Wrong facts? Ask which claims to verify and provide trusted sources.
Wrong tone? Paste an example of the tone you want.', FALSE FROM courses WHERE slug = 'prompt-engineering-foundations'
ON CONFLICT (course_id, order_index) DO NOTHING;
INSERT INTO lessons (course_id, title, order_index, duration_minutes, video_url, notes, is_free_preview)
SELECT id, 'Building a prompt library', 5, 8, 'https://videos.novaris.example/prompt-engineering-foundations/lesson-5.mp4', 'Turn winning prompts into templates with [placeholders].
Keep a team library with a short note on when to use each prompt.
Review templates monthly — models improve and so should your prompts.', FALSE FROM courses WHERE slug = 'prompt-engineering-foundations'
