SELECT l.id, 'How does a language model mainly produce its answers?', '["It looks up every answer live on the internet","It predicts likely next words from patterns it learned","It copies a single trusted website","It asks a human expert in the background"]'::jsonb, 1, 'Language models generate text word by word, predicting what is most likely to come next based on their training.' FROM lessons l JOIN courses c ON c.id = l.course_id WHERE c.slug = 'ai-basics-for-everyone' AND l.order_index = 1
ON CONFLICT (lesson_id, question) DO NOTHING;
