VALUES ('cloud-cost-planning-template', 'Cloud Cost Planning Template', 'Estimate and control AI spending', 'Cloud & AI', 'Template', 'Intermediate', 'XLSX', '640 KB', '6 sheets', 12, 4.6, 2740, 'Estimate token and request costs, plan low, expected and high scenarios, and track monthly spending against budget alerts.', '["Token and request cost estimator","Monthly budget tracker","Scenario planner (low / expected / high)","Alert threshold guide"]'::jsonb, '[{"title":"Cost formula","text":"(Input tokens × input price + output tokens × output price) × requests per month = monthly model cost."},{"title":"Scenarios","text":"Plan three cases: 1,000, 10,000 and 100,000 requests a month. Budget for the middle one."},{"title":"Alerts","text":"Set budget alerts at 50%, 80% and 100% of your monthly limit."}]'::jsonb, '["#0f766e","#2563eb"]'::jsonb, FALSE, FALSE, '2026-06-08')
