VALUES ('cloud-ai-starter-toolkit', 'Cloud & AI Starter Toolkit', 'Launch your first cloud AI project', 'Cloud & AI', 'Toolkit', 'Intermediate', 'ZIP', '22.6 MB', '18 files', 34, 4.8, 1980, 'Architecture templates, setup guides for the three major clouds, starter code snippets and a security checklist in one download.', '["Architecture diagram templates","Setup guides for Azure, Google Cloud and AWS","Starter code snippets","Security checklist","Cost planner (XLSX)"]'::jsonb, '[{"title":"Architecture","text":"User → web app → your API (keys stay here) → AI model → response with sources."},{"title":"First step","text":"Create a separate project or resource group for AI experiments so costs are easy to track."},{"title":"Reliability","text":"Always set a timeout and retry with backoff when calling an AI API."}]'::jsonb, '["#2563eb","#f59e0b"]'::jsonb, FALSE, FALSE, '2026-10-03')
ON CONFLICT (slug) DO NOTHING;
