VALUES ('lesson-planning-prompt-pack', 'Lesson Planning Prompt Pack', '50 prompts to plan lessons in minutes', 'AI for Teachers', 'Prompt Pack', 'Beginner', 'PDF', '1.9 MB', '50 prompts', 8, 4.9, 12380, 'Fifty prompts for planning, differentiating and assessing lessons — including low-tech options for classrooms with one projector or none.', '["50 prompts for planning, differentiation and assessment","Subject-specific sections","Low-tech classroom options","Example outputs"]'::jsonb, '[{"title":"Lesson plan","text":"Create a 40-minute lesson plan on [topic] for [grade] students with [number] learners and one projector. Include a starter, main activity and exit ticket."},{"title":"Differentiate","text":"Adapt this activity for three groups: learners who need support, on-track learners and fast finishers: [activity]"},{"title":"Local examples","text":"Give 5 examples of [concept] from everyday life in [country] that students will recognise."}]'::jsonb, '["#16a34a","#2563eb"]'::jsonb, TRUE, TRUE, '2025-12-15')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO digital_products (slug, title, subtitle, category, product_type, level, format, file_size, page_or_item_count, price_usd, rating, download_count, description, whats_included, preview_items, cover_gradient, is_featured, is_bestseller, created_at)
VALUES ('ai-classroom-policy-template', 'AI Classroom Policy Template', 'Clear, fair rules for AI use in school', 'AI for Teachers', 'Template', 'Beginner', 'DOCX', '290 KB', '8 pages', 0, 4.8, 9640, 'An editable school AI policy with a student-friendly version, a letter for parents and a classroom poster.', '["Editable school AI policy","Student-friendly version","Parent letter template","Acceptable-use poster"]'::jsonb, '[{"title":"Purpose","text":"AI tools may be used to support learning, not to replace it. Students must be able to explain any work they submit."},{"title":"Student rule","text":"If you used AI, say how: “I used AI to check my grammar” or “AI suggested ideas that I then developed.”"},{"title":"Privacy","text":"Never enter your full name, address or photos of classmates into an AI tool."}]'::jsonb, '["#0d9488","#7c3aed"]'::jsonb, FALSE, FALSE, '2026-01-20')
ON CONFLICT (slug) DO NOTHING;
