VALUES ('student-feedback-templates', 'Student Feedback Templates', 'Kind, specific feedback in half the time', 'AI for Teachers', 'Template', 'Intermediate', 'DOCX', '760 KB', '30 templates', 11, 4.7, 4170, 'Thirty feedback templates by subject, a glow-and-grow comment bank and prompts that personalise feedback for each learner.', '["30 feedback templates by subject","Glow-and-grow comment bank","AI prompts to personalise feedback","Rubric builder"]'::jsonb, '[{"title":"Glow and grow","text":"Glow: You explained [strength] clearly with a strong example. Grow: Next time, add [improvement] to make your argument even stronger."},{"title":"Personalise","text":"Rewrite this feedback for a 12-year-old in an encouraging tone, max 60 words. Do not change the main point: [feedback]"},{"title":"Rubric","text":"Create a 4-level rubric for [task] with criteria for content, structure and language."}]'::jsonb, '["#c026d3","#f59e0b"]'::jsonb, FALSE, FALSE, '2026-04-28')
ON CONFLICT (slug) DO NOTHING;
