VALUES ('ai-activities-workbook', 'AI Activities Workbook', '25 classroom activities about AI', 'AI for Teachers', 'Workbook', 'Beginner', 'PDF', '7.2 MB', '25 activities', 13, 4.9, 3560, 'Twenty-five printable activities that help students aged 10–18 understand AI — many need no devices at all.', '["25 printable activities (ages 10–18)","Unplugged activities for low-tech classrooms","Teacher notes and timings","Discussion questions on AI ethics"]'::jsonb, '[{"title":"Human or AI?","text":"Students read 6 short texts and vote on which were written by AI. Discuss: what clues did you use?"},{"title":"Train the robot","text":"In pairs, one student writes step-by-step instructions for a simple task; the other follows them exactly. What went wrong?"},{"title":"Fair or unfair?","text":"Discuss: an AI decides who gets a school scholarship. What could go wrong, and who should check it?"}]'::jsonb, '["#2563eb","#10b981"]'::jsonb, FALSE, FALSE, '2026-09-01')
ON CONFLICT (slug) DO NOTHING;
