VALUES ('ai-starter-bundle', 'AI Starter Bundle', 'Four best-sellers to start your AI journey', 'AI Basics', 'Bundle', 'Beginner', 'ZIP', '13.5 MB', '4 products', 24.99, 4.8, 2586, 'Our most popular beginner resources in one download: a 30-day workbook, everyday and power prompt packs, and the AI glossary flashcards.', '["My First 30 Days with AI Workbook — 42 pages","Everyday AI Prompt Pack — 60 prompts","AI Glossary Flashcards — 80 cards","100 Power Prompts Pack — 100 prompts"]'::jsonb, '[{"title":"My First 30 Days with AI Workbook","text":"Explain what you can and cannot help me with, in 5 bullet points."},{"title":"Everyday AI Prompt Pack","text":"Write a polite reply to this email declining the meeting but proposing two alternative times next week: [paste email]"},{"title":"AI Glossary Flashcards","text":"A small chunk of text (often part of a word) that a language model reads and writes. Pricing and limits are counted in tokens."}]'::jsonb, '["#7c3aed","#f5c76b"]'::jsonb, TRUE, TRUE, '2026-10-20')
ON CONFLICT (slug) DO NOTHING;
