VALUES ('business-growth-bundle', 'Business Growth Bundle', 'Market, sell and serve customers with AI', 'AI for Business', 'Bundle', 'Intermediate', 'ZIP', '24.3 MB', '4 products', 59.99, 4.8, 1314, 'Everything a growing business needs: the marketing prompt pack, small business toolkit, customer service templates and agent workflow templates.', '["AI Marketing Prompt Pack — 75 prompts","Small Business AI Toolkit — 14 files","AI Customer Service Templates — 40 templates","Agent Workflow Templates — 10 workflows"]'::jsonb, '[{"title":"AI Marketing Prompt Pack","text":"Here are 3 posts we love: [paste]. Describe our brand voice in 5 rules, then rewrite this draft to match: [draft]"},{"title":"Small Business AI Toolkit","text":"Which 3 tasks take your team the most time each week, and are they mostly reading or writing text? Those are your first AI candidates."},{"title":"AI Customer Service Templates","text":"Hi [name], thank you for your patience. Your order [number] is delayed because [reason]. It will arrive by [date]. As a thank-you, here is [offer]."}]'::jsonb, '["#ea580c","#4f46e5"]'::jsonb, TRUE, FALSE, '2026-10-25')
